const tornadoColor = 'red';
const tornadoWidth = 50;
const tornadoLength = 200;
const tornadoSpeed = 2;

let tornadoX = -tornadoWidth;
let tornadoY = H / 2 - tornadoLength / 2;

function drawTornado() {
    ctx.fillStyle = tornadoColor;
    ctx.fillRect(tornadoX, tornadoY, tornadoWidth, tornadoLength);
}

function updateTornado() {
    tornadoX += tornadoSpeed;
    if (tornadoX > W) {
        tornadoX = -tornadoWidth;
    }
}

