// Witch wings
ctx.fillStyle = '#888';
ctx.beginPath();
ctx.moveTo(W * 0.1, H * 0.5);
ctx.lineTo(W * 0.2, H * 0.4);
ctx.lineTo(W * 0.3, H * 0.5);
ctx.closePath();
ctx.fill();
ctx.beginPath();
ctx.moveTo(W * 0.1, H * 0.5);
ctx.lineTo(W * 0.2, H * 0.6);
ctx.lineTo(W * 0.3, H * 0.5);
ctx.closePath();
ctx.fill();

// Witch flying motion
ctx.save();
ctx.translate(W * 0.2, H * 0.5);
ctx.rotate(Math.PI / 10);
ctx.drawImage(canvas, 0, 0, W, H, -W * 0.1, -H * 0.1, W * 0.2, H * 0.2);
ctx.restore();

// Define colors
const backgroundColor = '#f0e68c';
const dogHouseColor = '#8b4513';
const dogColor = '#e9967a';
const tailColor = '#000000';

// Draw background
ctx.fillStyle = backgroundColor;
ctx.fillRect(0, 0, W, H);

// Draw dog house
ctx.fillStyle = dogHouseColor;
ctx.fillRect(W / 2 - 50, H - 100, 100, 100);

// Draw dog
ctx.fillStyle = dogColor;
ctx.fillRect(W / 2 - 25, H - 150, 50, 50);

// Draw tail
ctx.beginPath();
ctx.moveTo(W / 2 - 25, H - 150);
ctx.lineTo(W / 2 - 10, H - 130);
ctx.lineTo(W / 2 - 25, H - 120);
ctx.closePath();
ctx.fillStyle = tailColor;
ctx.fill();

// Draw tail end
ctx.beginPath();
ctx.arc(W / 2 - 10, H - 130, 5, 0, Math.PI * 2);
ctx.fillStyle = tailColor;
ctx.fill();
